import sys

def solve():
    input = sys.stdin.read().splitlines()
    T = int(input[0])
    for i in range(1, T+1):
        S = input[i]
        n = len(S)

        def compute_cost(target):
            cost = 0
            i = 0
            while i < n:
                if S[i] != target:
                    cost += 1
                    i += 1
                else:
                    j = i
                    while j < n and S[j] == target:
                        j += 1
                    if j - i > 1:
                        cost += 1
                    i = j
            return cost

        cost_all_0 = compute_cost('0')
        cost_all_1 = compute_cost('1')
        print(min(cost_all_0, cost_all_1))

solve()
